-- Invoicing (請求, docs/design/18-invoicing.md §1, §12).
-- Generated by `prisma migrate dev --create-only` (the columns, the index and the foreign keys), then
-- the body invariants of §1 added by hand at the end (Prisma leaves functions and triggers alone when
-- it diffs the schema):
--
-- 1. invoice cannot be deleted (a document is voided instead) nor truncated.
-- 2. A draft may change anything, including being issued or discarded (status -> void).
-- 3. Once issued, only the state columns change: status, payments, sent_at, sent_to, voided_at,
--    void_reason, pdf_document_id (set once, from NULL) and updated_at. The body (type, number,
--    partner, dates, title, lines, amounts, snapshots, source, journal entry …) never does.
-- 4. An issued document never goes back to draft, and a void one never changes again.

-- AlterTable
ALTER TABLE "invoice" ADD COLUMN     "issued_at" TIMESTAMPTZ(6),
ADD COLUMN     "note" TEXT,
ADD COLUMN     "prices_include_tax" BOOLEAN NOT NULL DEFAULT false,
ADD COLUMN     "recipient_snapshot" JSONB,
ADD COLUMN     "revenue_account_id" TEXT,
ADD COLUMN     "segment_id" TEXT,
ADD COLUMN     "sent_at" TIMESTAMPTZ(6),
ADD COLUMN     "sent_to" TEXT,
ADD COLUMN     "void_reason" TEXT,
ADD COLUMN     "voided_at" TIMESTAMPTZ(6);

-- CreateIndex
CREATE INDEX "invoice_status_due_date_idx" ON "invoice"("status", "due_date");

-- AddForeignKey
ALTER TABLE "invoice" ADD CONSTRAINT "invoice_revenue_account_id_fkey" FOREIGN KEY ("revenue_account_id") REFERENCES "account"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "invoice" ADD CONSTRAINT "invoice_segment_id_fkey" FOREIGN KEY ("segment_id") REFERENCES "segment"("id") ON DELETE SET NULL ON UPDATE CASCADE;

-- ---------------------------------------------------------------------------
-- invoice: no DELETE; after the issue only the state columns change
-- ---------------------------------------------------------------------------

CREATE FUNCTION "ledger_invoice_guard"() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ledger guard: invoice % cannot be deleted (void it instead)', OLD."id";
  END IF;

  -- A draft has no number and nothing in the ledger yet: its body is free.
  IF OLD."status" = 'draft' THEN
    RETURN NEW;
  END IF;

  IF OLD."status" = 'void' THEN
    IF to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
      RAISE EXCEPTION 'ledger guard: invoice % is void and cannot change', OLD."id";
    END IF;
    RETURN NEW;
  END IF;

  IF NEW."status" = 'draft' THEN
    RAISE EXCEPTION 'ledger guard: invoice % was issued and cannot go back to draft', OLD."id";
  END IF;

  -- Deny by default: every column except the state columns must stay as it is.
  IF (to_jsonb(NEW) - 'status' - 'payments' - 'sent_at' - 'sent_to' - 'voided_at' - 'void_reason'
        - 'pdf_document_id' - 'updated_at')
     IS DISTINCT FROM (to_jsonb(OLD) - 'status' - 'payments' - 'sent_at' - 'sent_to' - 'voided_at'
        - 'void_reason' - 'pdf_document_id' - 'updated_at') THEN
    RAISE EXCEPTION 'ledger guard: invoice % was issued; its body is immutable (only status, payments, sent_at, sent_to, voided_at, void_reason and pdf_document_id may change)',
      OLD."id";
  END IF;

  IF OLD."pdf_document_id" IS NOT NULL AND NEW."pdf_document_id" IS DISTINCT FROM OLD."pdf_document_id" THEN
    RAISE EXCEPTION 'ledger guard: pdf_document_id of invoice % is already set', OLD."id";
  END IF;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "invoice_guard"
  BEFORE UPDATE OR DELETE ON "invoice"
  FOR EACH ROW EXECUTE FUNCTION "ledger_invoice_guard"();

CREATE TRIGGER "invoice_reject_truncate"
  BEFORE TRUNCATE ON "invoice"
  FOR EACH STATEMENT EXECUTE FUNCTION "ledger_reject_truncate"();
